/// Local callback server and browser flow for the AIIN (aiin.by) sign-in.
///
/// The AIIN OAuth proxy flow accepts any client redirect URI, so the server
/// binds an EPHEMERAL loopback port — no fixed-port collisions with other
/// local tools (unlike the ChatGPT Codex flow, whose registered redirect
/// pins ports 1455/1457).
library;

import 'dart:async';
import 'dart:convert' show HtmlEscape;
import 'dart:io';

import 'package:http/http.dart' as http;

import 'package:flutter_agent_harness/flutter_agent_harness.dart';

import 'openrouter_oauth_server.dart'
    show
        authorizationUrlPrefix,
        browserLaunchSkippedMessage,
        defaultBrowserLaunchPolicy,
        openBrowser;

/// One OAuth proxy redirect caught by [AiinCallbackServer].
final class AiinCallback {
  const AiinCallback({
    this.code,
    this.state,
    this.error,
    this.errorDescription,
  });

  final String? code;
  final String? state;
  final String? error;
  final String? errorDescription;

  /// Whether the redirect carries a usable authorization code.
  bool get succeeded => code != null && code!.isNotEmpty && error == null;

  /// Parses a redirect URL that never reached the loopback server — the
  /// `ASWebAuthenticationSession` scheme interception
  /// (`callbackScheme: 'http'`, gh-1044 AC9) hands the callback URL
  /// straight back to the caller, so the same `code`/`state`/`error`
  /// query the server would see arrives as a string instead of an HTTP
  /// request.
  factory AiinCallback.fromRedirectUrl(String url) {
    final query =
        Uri.tryParse(url)?.queryParameters ?? const <String, String>{};
    return AiinCallback(
      code: query['code'],
      state: query['state'],
      error: query['error'],
      errorDescription: query['error_description'],
    );
  }
}

/// Loopback HTTP server catching the AIIN OAuth redirect.
///
/// Dual-stack on the loopback interface (gh-1044 review): the primary
/// IPv4 listener plus a best-effort IPv6 listener on the same port, so
/// the fallback leg (an in-sheet redirect that loads the server for
/// real) is reachable no matter how the client resolves the host — a
/// `localhost` label may answer `::1`, and the literal `127.0.0.1` needs
/// the IPv4 listener. The IPv6 listener is optional: hosts without IPv6
/// loopback skip it (debugPrint) and the flow keeps working over IPv4.
final class AiinCallbackServer {
  HttpServer? _server;
  HttpServer? _server6;
  Completer<AiinCallback?>? _result;
  Timer? _timer;

  /// The host the callback URL advertises. The flow advertises the
  /// literal `127.0.0.1` on every surface (scheme interception ignores
  /// the host; the fallback leg needs an address that reaches the IPv4
  /// bind without resolver ambiguity); other values only for tests.
  String callbackHost = '127.0.0.1';

  /// The redirect URI to register with [initiateAiinOAuth]
  /// (`http://<host>:<ephemeral-port>/callback`).
  String? get callbackUrl {
    final server = _server;
    return server == null
        ? null
        : 'http://$callbackHost:${server.port}/callback';
  }

  /// Binds the loopback server and returns the redirect URI.
  Future<String> start({
    Duration timeout = const Duration(minutes: 5),
    String callbackHost = '127.0.0.1',
  }) async {
    this.callbackHost = callbackHost;
    await close();
    _result = Completer<AiinCallback?>();
    _server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
    _timer = Timer(timeout, () => _complete(null));
    _server!.listen(_handle, onDone: () => _complete(null));
    // Best-effort IPv6 loopback on the same port: a redirect addressed
    // `localhost` can resolve to `::1` (gh-1044 review) — the fallback
    // leg must answer there too. Optional: no IPv6, no problem.
    try {
      _server6 = await HttpServer.bind(
        InternetAddress.loopbackIPv6,
        _server!.port,
        v6Only: true,
      );
      _server6!.listen(_handle, onDone: () => _complete(null));
    } on IOException catch (error) {
      _server6 = null;
      stderr.writeln(
        '[AIIN] no IPv6 loopback listener (the fallback leg stays '
        'IPv4-only): $error',
      );
    }
    return callbackUrl!;
  }

  Future<AiinCallback?> waitForCallback() => _result?.future ?? Future.value();

  Future<void> _handle(HttpRequest request) async {
    if (request.method != 'GET' || request.uri.path != '/callback') {
      request.response.statusCode = HttpStatus.notFound;
      unawaited(request.response.close());
      return;
    }
    final callback = AiinCallback(
      code: request.uri.queryParameters['code'],
      state: request.uri.queryParameters['state'],
      error: request.uri.queryParameters['error'],
      errorDescription: request.uri.queryParameters['error_description'],
    );
    request.response.headers.contentType = ContentType.html;
    request.response.statusCode = callback.succeeded
        ? HttpStatus.ok
        : HttpStatus.badRequest;
    request.response.write(_callbackPage(callback));
    // Flush the page before _complete force-closes the server, or the
    // browser may see a truncated response.
    await request.response.close();
    _complete(callback);
  }

  void _complete(AiinCallback? value) {
    final completer = _result;
    if (completer != null && !completer.isCompleted) completer.complete(value);
    unawaited(close());
  }

  Future<void> close() async {
    _timer?.cancel();
    _timer = null;
    final server = _server;
    final server6 = _server6;
    _server = null;
    _server6 = null;
    if (server != null) await server.close(force: true);
    if (server6 != null) await server6.close(force: true);
  }
}

/// Renders the HTML page shown in the browser after the redirect.
String _callbackPage(AiinCallback callback) {
  final success = callback.succeeded;
  final title = success ? 'AIIN connected' : 'AIIN sign-in failed';
  final message = success
      ? 'You can close this tab and return to Fa.'
      : const HtmlEscape().convert(
          callback.errorDescription ??
              callback.error ??
              'No authorization code received.',
        );
  return '<!doctype html><title>$title</title>'
      '<style>body{font-family:system-ui,sans-serif;max-width:36rem;margin:5rem auto;text-align:center}</style>'
      '<h1>$title</h1><p>$message</p>';
}

/// The mobile auth-session surface closed WITHOUT a callback — a user
/// cancel (iOS swipe-dismissal). Thrown by [runAiinConnectCliFlow] under
/// `cancelWhenOpenSettles`; the app's mobile branch catches it and
/// surfaces the visible failure state (gh-1044 I4 — SSO is the only
/// path, never a paste sheet).
final class AiinSurfaceClosedException implements Exception {
  const AiinSurfaceClosedException();

  @override
  String toString() =>
      'AiinSurfaceClosedException: the sign-in surface closed without a '
      'callback (user cancel)';
}

/// Runs the full AIIN connect flow for CLI/desktop hosts:
///
/// 1. binds the loopback callback server (ephemeral port),
/// 2. initiates the OAuth proxy flow for [provider],
/// 3. opens the system browser at the sign-in URL ([openBrowserFn]),
/// 4. catches the redirect, exchanges the code for JWTs,
/// 5. registers an API key with the access JWT.
///
/// Returns null on timeout/cancel or a reported service error (status is
/// printed through [onStatus]); throws [AiinAuthException] never — service
/// failures surface through [onStatus] so callers can treat null as "not
/// connected".
Future<AiinConnectResult?> runAiinConnectCliFlow({
  required void Function(String) onStatus,
  Future<bool> Function(String) openBrowserFn = openBrowser,
  bool Function() shouldOpenBrowserFn = defaultBrowserLaunchPolicy,
  http.Client? client,
  String authBaseUrl = aiinAuthBaseUrl,
  Duration timeout = const Duration(minutes: 5),

  /// Called once the callback wait settles — when the callback lands OR
  /// the timeout/cancel path gives up — before the exchange/return. The
  /// mobile auth-session sheet dismisses itself here (a stale sheet
  /// closes too): the session intercepts the `http://` redirect
  /// (`callbackScheme: 'http'`, gh-1044 AC9) and hands the callback URL
  /// back through [interceptedCallback] instead of navigating it, so
  /// the sheet must be closed programmatically to hand the user back to
  /// the app. Optional — desktop callers skip it.
  void Function()? onCallback,

  /// Treats a successful open completion before any callback as a user
  /// cancel — throws [AiinSurfaceClosedException] — instead of waiting
  /// out [timeout]. For surfaces that resolve without a completion value
  /// (an external browser launch): when the launch future settles with no
  /// callback and no [interceptedCallback] channel, a user abandonment
  /// must short-circuit, not leave dead air. When [interceptedCallback]
  /// IS present the sheet's resolution rides it alone (its null IS the
  /// cancel) and this flag is ignored — the two signals come from the
  /// same resolution, and the open-settle path would only race the
  /// callback URL's delivery. Desktop callers leave this off (default
  /// false).
  bool cancelWhenOpenSettles = false,

  /// The host the callback URL advertises: the literal `127.0.0.1` on
  /// every surface (scheme interception ignores the host; the fallback
  /// leg needs an address that reaches the IPv4 bind without resolver
  /// ambiguity) — other values only for tests.
  String callbackHost = '127.0.0.1',

  /// How long an already-landed callback waits for the open surface to
  /// settle (gh-1378) — injectable so tests pay no real wall clock.
  Duration sheetSettleGrace = _sheetSettleGrace,

  /// The auth-session surface's completion value (gh-1044 AC9): resolves
  /// with the callback URL the native scheme interception caught
  /// (`callbackScheme: 'http'`), or null when the sheet closed without
  /// one (user cancel). When it delivers a URL the flow settles from it
  /// directly — completion no longer depends on the redirect loading the
  /// loopback server inside the sheet. The loopback server stays armed as
  /// the fallback leg (older surfaces still navigate the redirect for
  /// real); whichever leg lands first wins the race. This future is the
  /// sheet's single completion channel — the
  /// [cancelWhenOpenSettles] open-settle cancel does not apply while it
  /// exists.
  Future<String?> Function()? interceptedCallback,
}) async {
  final server = AiinCallbackServer();
  final redirectUri = await server.start(
    timeout: timeout,
    callbackHost: callbackHost,
  );
  try {
    // The hosted sign-in page: AIIN lists every provider, runs the whole
    // round-trip (silent for an existing session) and redirects back with
    // the code + our state.
    final state = aiinGenerateState();
    final loginUrl = buildAiinLoginUrl(
      redirectUri: redirectUri,
      state: state,
      // `desktop` is the client_type whose redirect shape is an arbitrary
      // localhost loopback URI — the mobile apps use the same shape. There
      // is no `mobile` value in AIIN's contract (the web build sends
      // `web`), so desktop parity is deliberate here.
      clientType: 'desktop',
      authBaseUrl: authBaseUrl,
    );
    onStatus('listening for the AIIN callback on $redirectUri');
    // Arm the callback wait and the browser surface CONCURRENTLY: the
    // mobile auth session resolves its open future only when the sheet
    // CLOSES, and the sheet is dismissed through [onCallback] — awaiting
    // the open first would deadlock the mobile flow. Open FAILURES (the
    // session cannot start) surface promptly through the race instead of
    // stalling until the callback timeout.
    final callbackFuture = server.waitForCallback();
    final opened = _openAiinBrowser(
      loginUrl.toString(),
      openBrowserFn,
      onStatus,
      launchBrowser: shouldOpenBrowserFn(),
    );
    final intercepted = interceptedCallback?.call();
    AiinCallback? callback;
    try {
      final (won, source) = await _firstCallbackOrOpenError(
        callbackFuture,
        opened,
        cancelWhenOpenSettles: cancelWhenOpenSettles,
        intercepted: intercepted,
      );
      callback = won;
      // gh-1044 AC2: the winning leg is answerable from the log alone —
      // interception (the fixed path) vs a real loopback hit (the
      // fallback leg) discriminates F2 from F1 without a device debugger.
      // A null callback (timeout) keeps _settleAiinCallback's message.
      if (callback != null) {
        onStatus(switch (source) {
          _AiinCallbackSource.interceptedRedirect =>
            'AIIN redirect intercepted by the sign-in sheet (callback URL '
                'returned to the flow)',
          _AiinCallbackSource.loopbackServer =>
            'AIIN callback landed on the loopback server',
        });
      }
    } on AiinSurfaceClosedException {
      onStatus(
        'the sign-in sheet closed without completing the sign-in '
        '(no callback returned — user cancel)',
      );
      rethrow;
    }
    onCallback?.call();
    try {
      // gh-1378: once the callback has landed, the open surface's settle
      // is cosmetic — the dismissal handing the user back to the app. It
      // must never hold the flow unbounded: a sheet whose completion
      // never fires (the deprecated-for-`http` interception dead, a lost
      // dismissal) kept the latch "in progress" forever with NO log
      // after the callback line. A short grace keeps the ordering (the
      // sheet had its chance to close before the exchange starts); the
      // timeout is a status line, never dead air.
      await opened.timeout(sheetSettleGrace);
    } on TimeoutException {
      onStatus(
        'the sign-in sheet did not close after the callback — '
        'continuing without it',
      );
    } on Object {
      // Late open failure after the callback won: the flow is settling
      // and the open surface is already gone (e.g. the native side fails
      // the pending session when the dismissal tears it down). Swallow —
      // the landed callback must always settle the flow.
    }
    return await _settleAiinCallback(
      callback,
      state,
      authorizationUrl: loginUrl.toString(),
      client: client,
      authBaseUrl: authBaseUrl,
      onStatus: onStatus,
    );
  } on AiinAuthException catch (error) {
    onStatus('AIIN sign-in failed: ${error.message}');
    return null;
  } finally {
    await server.close();
  }
}

/// Where the winning callback came from — the gh-1044 AC2 discriminator
/// (interception vs a real loopback hit).
enum _AiinCallbackSource { loopbackServer, interceptedRedirect }

/// How long the already-won callback waits for the browser/sheet surface
/// to settle before the exchange proceeds (gh-1378). Long enough for a
/// dismissal animation, short enough that a dead sheet cannot stall the
/// flow past it.
const _sheetSettleGrace = Duration(seconds: 3);

/// Resolves with the first of [callbackFuture] (a landed callback or the
/// timeout), an [intercepted] callback URL (gh-1044 AC9), an [opened]
/// failure, or — when [cancelWhenOpenSettles] — a successful [opened]
/// completion, or an [intercepted] null ([AiinSurfaceClosedException]): an
/// auth-session sheet that closed WITHOUT returning a callback URL is a
/// user cancel, not a reason to wait out the callback timeout. A late
/// open error after the callback won is dropped from the race here and
/// swallowed by the caller's `await opened` — the landed callback always
/// settles the flow.
///
/// When [intercepted] is present it is the sheet's SINGLE completion
/// channel — both the callback URL and the cancel (null) ride it — so the
/// [opened] settle never duplicates the cancel (gh-1044): the mobile
/// wrapper resolves `opened` and [intercepted] from the SAME sheet
/// resolution, and a Dart async function's `return` completes its future
/// SYNCHRONOUSLY (VM `_returnAsyncNotFuture` → `_completeWithValue`) while
/// `Completer.complete` defers its listeners to a LATER microtask — an
/// `opened`-settle cancel evaluated in that cascade would always judge
/// the pending [interceptedCallback] incomplete and steal the race from a
/// callback URL sitting in the very next microtask. With no [intercepted]
/// channel (an external browser that gives no completion value),
/// [cancelWhenOpenSettles] keeps its original meaning.
Future<(AiinCallback?, _AiinCallbackSource)> _firstCallbackOrOpenError(
  Future<AiinCallback?> callbackFuture,
  Future<void> opened, {
  required bool cancelWhenOpenSettles,
  Future<String?>? intercepted,
}) {
  final openError = Completer<Never>();
  final surfaceClosed = Completer<Never>();
  final interceptedCallback = Completer<(AiinCallback?, _AiinCallbackSource)>();
  if (intercepted != null) {
    _wireInterceptedChannel(
      intercepted: intercepted,
      openError: openError,
      surfaceClosed: surfaceClosed,
      interceptedCallback: interceptedCallback,
    );
  }
  unawaited(
    opened.then(
      (_) {
        // With an intercepted channel the sheet's resolution is reported
        // through it alone (null = user cancel) — never duplicated here.
        // See the doc comment for the scheduling asymmetry that makes the
        // duplication a lost race for the intercepted URL.
        if (cancelWhenOpenSettles &&
            intercepted == null &&
            !surfaceClosed.isCompleted &&
            !interceptedCallback.isCompleted) {
          surfaceClosed.completeError(const AiinSurfaceClosedException());
        }
      },
      onError: (Object error, StackTrace stackTrace) {
        if (!openError.isCompleted) openError.completeError(error, stackTrace);
      },
    ),
  );
  openError.future.ignore();
  surfaceClosed.future.ignore();
  return Future.any([
    callbackFuture.then(
      (callback) => (callback, _AiinCallbackSource.loopbackServer),
    ),
    openError.future,
    surfaceClosed.future,
    interceptedCallback.future,
  ]);
}

/// Arms the intercepted-callback channel's listeners (gh-1044 AC9) on the
/// shared completers of [_firstCallbackOrOpenError]: a callback URL wins
/// the race as [_AiinCallbackSource.interceptedRedirect]; a null is the
/// user cancel — [AiinSurfaceClosedException] on [surfaceClosed] — and a
/// channel error surfaces on [openError] ahead of the callback timeout
/// (the same prompt-failure contract as an open failure). Only the first
/// settle wins: every completion checks its completer first.
void _wireInterceptedChannel({
  required Future<String?> intercepted,
  required Completer<Never> openError,
  required Completer<Never> surfaceClosed,
  required Completer<(AiinCallback?, _AiinCallbackSource)> interceptedCallback,
}) {
  unawaited(
    intercepted.then(
      (url) {
        if (url != null) {
          if (!interceptedCallback.isCompleted) {
            interceptedCallback.complete((
              AiinCallback.fromRedirectUrl(url),
              _AiinCallbackSource.interceptedRedirect,
            ));
          }
          return;
        }
        // The sheet closed without returning a callback URL — a user
        // cancel (the same semantics as cancelWhenOpenSettles).
        if (!surfaceClosed.isCompleted && !interceptedCallback.isCompleted) {
          surfaceClosed.completeError(const AiinSurfaceClosedException());
        }
      },
      onError: (Object error, StackTrace stackTrace) {
        if (!openError.isCompleted) {
          openError.completeError(error, stackTrace);
        }
      },
    ),
  );
}

/// Opens the sign-in surface, reporting the launch outcome and ALWAYS the
/// authorization URL (gh-1450): the skip/opened/could-not-open hint line,
/// then the consistent `authorization URL:` line in every outcome —
/// including a throwing [openBrowserFn], which still surfaces through the
/// race (the prompt-failure contract) after both lines are printed.
Future<void> _openAiinBrowser(
  String authUrl,
  Future<bool> Function(String) openBrowserFn,
  void Function(String) onStatus, {
  required bool launchBrowser,
}) async {
  try {
    if (!launchBrowser) {
      onStatus(browserLaunchSkippedMessage);
    } else if (await openBrowserFn(authUrl)) {
      onStatus('browser opened; sign in on the AIIN page');
    } else {
      onStatus('could not open browser automatically');
    }
  } on Object {
    onStatus('could not open browser automatically');
    onStatus('$authorizationUrlPrefix$authUrl');
    rethrow;
  }
  onStatus('$authorizationUrlPrefix$authUrl');
}

/// Validates the caught redirect and finishes the connect. Null = the
/// callback never arrived, reported a provider error, or failed the
/// state check. [authorizationUrl] rides the timeout status as the
/// last-chance rescue line (gh-1450 AC4).
Future<AiinConnectResult?> _settleAiinCallback(
  AiinCallback? callback,
  String expectedState, {
  required String authorizationUrl,
  required http.Client? client,
  required String authBaseUrl,
  required void Function(String) onStatus,
}) async {
  if (callback == null) {
    onStatus('no AIIN callback received (timeout or cancelled)');
    onStatus('$authorizationUrlPrefix$authorizationUrl');
    return null;
  }
  if (!callback.succeeded) {
    onStatus(
      'AIIN sign-in failed: ${callback.errorDescription ?? callback.error}',
    );
    return null;
  }
  if (callback.state != expectedState) {
    onStatus('AIIN sign-in callback was invalid (state mismatch)');
    return null;
  }
  // gh-1378: the exchange is the first post-callback step with no
  // status line before it — a slow or stalled exchange was
  // indistinguishable from a hang in the log. Announce it.
  onStatus('exchanging the AIIN authorization code...');
  return _finishAiinConnect(
    callback.code!,
    expectedState,
    client: client,
    authBaseUrl: authBaseUrl,
    onStatus: onStatus,
  );
}

/// Exchanges the code for JWTs and registers the durable `sk-aiin-...`
/// key. Null = a reported exchange/registration failure.
Future<AiinConnectResult?> _finishAiinConnect(
  String code,
  String state, {
  required http.Client? client,
  required String authBaseUrl,
  required void Function(String) onStatus,
}) async {
  try {
    final tokens = await exchangeAiinOAuthCode(
      code: code,
      state: state,
      client: client,
      authBaseUrl: authBaseUrl,
    );
    onStatus('AIIN authorized - registering an API key...');
    final apiKey = [REDACTED:Sensitive-Value] createAiinApiKey(
      accessToken: [REDACTED:Sensitive-Value],
      client: client,
    );
    onStatus('AIIN API key registered - finishing the connect');
    return AiinConnectResult(
      apiKey: [REDACTED:Sensitive-Value],
      tokens: tokens,
      email: aiinJwtEmail(tokens.accessToken),
    );
  } on AiinAuthException catch (error) {
    onStatus('AIIN setup failed: ${error.message}');
    return null;
  }
}

/// One shared "which models does this endpoint serve" dispatch for every
/// model picker (CLI settings flows, the app's chat/media/agent model
/// pages). Each wire dialect is its own class — add a new provider by
/// implementing [ModelListDialect] and registering it in
/// [modelListDialects], never by adding a branch here.
library;

import 'dart:async';
import 'dart:convert';

import 'package:http/http.dart' as http;
import 'package:meta/meta.dart';

import '../session/uuid.dart';
import 'chatgpt_codex_models.dart';
import 'chatgpt_oauth.dart';
import 'codemie_sso.dart';
import 'codex_transport.dart';
import 'copilot_oauth.dart';
import 'dial.dart';
import 'models_endpoint.dart';
import 'provider_common.dart'
    show effectiveProviderConnectTimeout, providerTimeoutsOverride;
import 'remote_catalog.dart';

/// The [fetchModelsForEndpoint] `provider` hints the dialects match on.
/// Connect flows persist these on registry entries (`CustomProvider.kind`)
/// so identity survives URL edits; [modelsDispatchHintFor]-style URL
/// mappers return the same values.
const String chatgptCodexDispatchHint = 'chatgpt-codex';
const String copilotDispatchHint = 'copilot';
const String dialDispatchHint = 'dial';

/// One provider's "how to list models" implementation. Each dialect
/// encapsulates its own detection (does this endpoint belong to me?) and
/// its own fetch (what URL, what auth, what shape the response has, how
/// to normalise ids). Pickers never see the internals — they just call
/// [fetchModelsForEndpoint] which delegates.
///
/// The [ModelListDialect.fetch] `onBundledFallback` parameter is optional
/// for dialects without a bundled offline catalog: keep it in the
/// override's signature and simply ignore it — only dialects that answer
/// from a bundled catalog when the live fetch fails ever invoke it.
/// (Adding the parameter is a breaking change for out-of-tree
/// implementers; called out in CHANGELOG.md.)
abstract final class ModelListDialect {
  /// Whether this dialect handles [baseUrl] (optionally with the
  /// provider's hint from the caller).
  bool matches(String baseUrl, String? provider);

  /// Fetches the model list. Implementations must answer an empty
  /// [ModelsEndpointInfo] on any error — the manual-entry fallback in
  /// the pickers depends on it. A dialect that answers from a bundled
  /// catalog because the live fetch failed (the Codex catalog today)
  /// invokes [onBundledFallback] so pickers can surface the provenance.
  Future<ModelsEndpointInfo> fetch(
    String baseUrl,
    String apiKey, {
    http.Client? client,
    void Function()? onBundledFallback,
  });

  /// Fetches the model list WITH the empty-answer diagnostic (gh-1990):
  /// the same answer as [fetch], carrying WHY it is empty when it is.
  /// The default wraps [fetch] with no diagnostic; dialects with named
  /// failure branches override it. [fetchModelsForEndpointReport]
  /// dispatches here.
  Future<ModelsFetchReport> fetchReport(
    String baseUrl,
    String apiKey, {
    http.Client? client,
    void Function()? onBundledFallback,
  }) async => ModelsFetchReport(
    info: await fetch(
      baseUrl,
      apiKey,
      client: client,
      onBundledFallback: onBundledFallback,
    ),
  );
}

/// The registered dialects, in precedence order. First match wins.
/// Adding a new provider = one new class + one entry here.
final List<ModelListDialect> modelListDialects = [
  _CodeMieDialect(),
  _DialDialect(),
  _CodexDialect(),
  _CopilotDialect(),
  _GoogleDialect(),
  _OpenAiCompatibleDialect(), // default — must stay last
];

/// Fetches the model list of [baseUrl], picking the wire dialect by
/// registration order. Any failure answers an empty info — callers always
/// keep their manual-entry fallback. When a dialect answers from its
/// bundled catalog instead of the live endpoint ([onBundledFallback]), the
/// picker can surface the provenance (the bundled-catalog note).
Future<ModelsEndpointInfo> fetchModelsForEndpoint(
  String baseUrl, {
  required String apiKey,
  String? provider,
  http.Client? client,
  void Function()? onBundledFallback,
}) async {
  final report = await fetchModelsForEndpointReport(
    baseUrl,
    apiKey: [REDACTED:Sensitive-Value],
    provider: provider,
    client: client,
    onBundledFallback: onBundledFallback,
  );
  return report.info;
}

/// Why a `/models` fetch answered empty — the named failure branch
/// (gh-1990): no picker may show a bare empty list again, every
/// silent-empty exit (token exchange / HTTP / tier routing / filter)
/// carries its reason.
@immutable
final class ModelsFetchDiagnostic {
  /// Creates the diagnostic; [stage] and [message] are the contract, the
  /// rest is best-effort structure for programmatic surfacing.
  const ModelsFetchDiagnostic({
    required this.stage,
    required this.message,
    this.path,
    this.httpStatus,
    this.timedOut = false,
    this.pathFailed = true,
    this.fetchedCount = 0,
    this.filteredCount = 0,
    this.hint,
  });

  /// The stage that produced this: the token exchange, the `/models`
  /// HTTP call, or the picker filter ([stageExchange], [stageModels],
  /// [stageFilter]). When BOTH credential paths failed, the dual-path
  /// combined diagnostic joins the two stage names with [stageDualJoiner]
  /// (e.g. `exchange+models`) — [stages] splits it back apart for
  /// programmatic consumers that match on the constants.
  final String stage;

  /// The exchange stage — `copilot_internal/v2/token` failed.
  static const stageExchange = 'exchange';

  /// The models stage — the `/models` HTTP call failed or answered empty.
  static const stageModels = 'models';

  /// The filter stage — `/models` answered, the picker filter dropped
  /// every entry.
  static const stageFilter = 'filter';

  /// The joiner of a dual-path combined [stage] (`exchange+models`) —
  /// the documented extension of the stage vocabulary for the
  /// both-credential-paths-failed diagnostic.
  static const stageDualJoiner = '+';

  /// Which credential path produced this: the exchanged-token path or
  /// the raw-PAT path (the dual-path provenance, gh-1606).
  final String? path;

  /// The exchanged-token path (the default credential route).
  static const pathExchange = 'exchange';

  /// The raw-PAT path (fine-grained PATs, the gh-1606 PAT mode).
  static const pathPatDirect = 'pat-direct';

  /// The one-line user-facing reason.
  final String message;

  /// The HTTP status when a request failed with one.
  final int? httpStatus;

  /// Whether the failure was the watchdog firing instead of an answer.
  final bool timedOut;

  /// Whether THIS path failed (exchange throw, non-200, timeout,
  /// transport) — as opposed to answering and the filter dropping the
  /// entries. The dual-path fallback retries only failed paths.
  final bool pathFailed;

  /// Entries the payload carried (the filter stage).
  final int fetchedCount;

  /// Entries the picker filter dropped (the filter stage).
  final int filteredCount;

  /// Optional remediation hint (tier host, PAT remedies, seat check).
  final String? hint;

  /// The individual stages of [stage] — one entry unless the dual-path
  /// combined diagnostic named both failing credential paths (then two,
  /// e.g. `[stageExchange, stageModels]`). Splitting on the documented
  /// [stageDualJoiner] keeps the combined form matchable for consumers.
  List<String> get stages => stage.split(stageDualJoiner);

  @override
  String toString() => message;
}

/// A `/models` fetch answer plus its provenance (gh-1990): the parsed
/// [ModelsEndpointInfo], the empty-answer [diagnostic], an optional
/// human-facing [note] (path fallback, partial filtering), and the
/// per-model filter drops.
///
/// The diagnostic contract is SCOPED (gh-1990 review round 2): dialects
/// that override [ModelListDialect.fetchReport] with named failure
/// branches (today the Copilot dialect) attach a diagnostic on every
/// empty answer; the DEFAULT keeps the legacy diagnostic-less shape
/// (null even when empty). A consumer must not assume
/// `diagnostic != null ⇔ isEmpty`.
@immutable
final class ModelsFetchReport {
  /// Creates the report. Dialects that override
  /// [ModelListDialect.fetchReport] with named failure branches (today
  /// the Copilot dialect) attach a [diagnostic] on every empty answer;
  /// the default keeps the legacy diagnostic-less shape (null even when
  /// empty) — an empty answer names its reason only where a dialect
  /// names it.
  const ModelsFetchReport({
    required this.info,
    this.diagnostic,
    this.note,
    this.droppedModels = const <(String, String)>[],
  });

  /// The parsed model list (ids, context windows, output caps).
  final ModelsEndpointInfo info;

  /// Why the answer is empty — set by dialects that name their failure
  /// branches (the Copilot dialect today); the default `fetchReport`
  /// answers null even when [isEmpty].
  final ModelsFetchDiagnostic? diagnostic;

  /// Optional provenance note even on success: the dual-path fallback
  /// note (which credential path answered), a partial-filter summary.
  final String? note;

  /// Per-model filter drops as (model id, drop reason) — populated even
  /// when some models were listed (AC2 transparency).
  final List<(String, String)> droppedModels;

  /// Whether the fetch answered no models.
  bool get isEmpty => info.$1.isEmpty;

  /// The one-line user-facing reason for an empty answer, with the
  /// remediation hint appended when present.
  String get reasonText {
    final d = diagnostic;
    if (d == null) return '';
    return d.hint == null ? d.message : '${d.message} — ${d.hint}';
  }

  /// The user-facing reason across BOTH answer kinds (gh-1990 review —
  /// the single formatting rule, no hand-rolled `message — hint` joins
  /// at the call sites): the diagnostic's [reasonText] when the fetch
  /// named a failed branch, else the provenance [note] (fallback path,
  /// partial filter). Null when neither is present — in particular for
  /// the default `fetchReport`'s legacy diagnostic-less empty answers
  /// (the non-Copilot dialects), which carry neither.
  String? get userFacingReason => diagnostic == null ? note : reasonText;
}

/// Fetches the model list of [baseUrl] WITH the empty-answer diagnostic
/// (gh-1990): the same dispatch as [fetchModelsForEndpoint], but the
/// answer carries WHY it is empty — the failed stage (token exchange /
/// HTTP / filter), the HTTP status, the timeout flag, the per-model
/// filter drops, and any remediation hint.
Future<ModelsFetchReport> fetchModelsForEndpointReport(
  String baseUrl, {
  required String apiKey,
  String? provider,
  http.Client? client,
  void Function()? onBundledFallback,
}) async {
  final effectiveClient = client ?? _dispatchHttpClientForTesting;
  for (final dialect in modelListDialects) {
    if (dialect.matches(baseUrl, provider)) {
      return dialect.fetchReport(
        baseUrl,
        apiKey,
        client: effectiveClient,
        onBundledFallback: onBundledFallback,
      );
    }
  }
  return ModelsFetchReport(
    info: (const <String>[], const <String, int>{}, const <String, int>{}),
    diagnostic: ModelsFetchDiagnostic(
      stage: ModelsFetchDiagnostic.stageModels,
      message: 'no model-list dialect handles this endpoint',
    ),
  );
}

http.Client? _dispatchHttpClientForTesting;

/// Test seam — routes every dialect's HTTP through [client] so widget
/// tests can pump the production dispatch path (no [ModelsEndpointFetcher]
/// override, real routing) without network. Null restores the per-dialect
/// default. Not part of the public API.
@visibleForTesting
void setModelsDispatchClientForTesting(http.Client? client) {
  _dispatchHttpClientForTesting = client;
}

