Future<List<String>> _fetchOpenAiCompatibleModels(
  String baseUrl, {
  required String apiKey,
  http.Client? client,
}) async {
  // The SHARED dispatch (gh-2466): the dialect carries the ain per-family
  // window correction and the endpoint-reported input modalities, so the
  // CLI's own fetch path cannot drift from the pickers' answers
  // (gh-1742: ONE window per model identity everywhere).
  final info = await fetchModelsForEndpoint(
    baseUrl,
    apiKey: apiKey,
    client: client,
  );
  final (ids, windows, maxTokens, modalities) = info;
  _modelContextWindows = windows;
  _modelMaxTokens = maxTokens;
  if (modalities.isNotEmpty) _modelInputModalities = modalities;
  return ids;
}

arguments.oldText:
Future<List<String>> _fetchOpenAiCompatibleModels(
  String baseUrl, {
  required String apiKey,
  http.Client? client,
}) async {
  final normalized = baseUrl.replaceAll(RegExp(r'/+$'), '');
  final uri = Uri.parse('$normalized/models');
  final headers = <String, String>{'Accept': 'application/json'};
  if (apiKey.isNotEmpty) headers['Authorization'] = 'Bearer $apiKey';
  try {
    final request = http.Request('GET', uri)..headers.addAll(headers);
    final response =
        await (client == null
                ? http.get(uri, headers: headers)
                : client.send(request).then(http.Response.fromStream))
            .timeout(const Duration(seconds: 15));
    if (response.statusCode != 200) return const [];
    final info = parseModelsResponse(response.body);
    // gh-2466: the AIN gateway stamps a blanket ≈1M window on every
    // unverified id — the curated per-family correction applies HERE
    // (the CLI's own fetch path) so the picker, the window registry and
    // the compaction trigger inherit the same numbers the dialect path
    // serves.
    final (ids, windows, maxTokens, modalities) = isAiinBaseUrl(baseUrl)
        ? normalizeAiinModelInfo(info)
        : info;
    _modelContextWindows = windows;
    _modelMaxTokens = maxTokens;
    if (modalities.isNotEmpty) _modelInputModalities = modalities;
    return ids;
  } on Object {
    return const [];
  }
}

